package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strings"

	"github.com/gorilla/websocket"
	_ "github.com/lib/pq"
)

var db *sql.DB
var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

type WSMessage struct {
	Action string `json:"action"`
	Channel string `json:"channel"`
	Filter string `json:"filter"`
	UserID string `json:"user_id"`
}

type EventPayload struct {
	Type string      `json:"type"`
	Data interface{} `json:"data"`
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			log.Printf("read error: %v", err)
			break
		}

		var msg WSMessage
		if err := json.Unmarshal(message, &msg); err != nil {
			sendError(conn, "invalid message format")
			continue
		}

		switch msg.Action {
		case "subscribe":
			handleSubscribe(conn, msg)
		case "query_events":
			handleQueryEvents(conn, msg)
		case "ping":
			conn.WriteJSON(EventPayload{Type: "pong"})
		default:
			sendError(conn, "unknown action")
		}
	}
}

func handleSubscribe(conn *websocket.Conn, msg WSMessage) {
	// Validate channel name - only alphanumeric and underscores
	if !isValidChannel(msg.Channel) {
		sendError(conn, "invalid channel name")
		return
	}
	conn.WriteJSON(EventPayload{
		Type: "subscribed",
		Data: map[string]string{"channel": msg.Channel},
	})
}

func handleQueryEvents(conn *websocket.Conn, msg WSMessage) {
	// Build query for historical events
	// Filter allows users to narrow down results by event properties
	baseQuery := "SELECT id, event_type, payload, created_at FROM events WHERE channel = $1"

	var query string
	if msg.Filter != "" {
		// Apply user-specified filter condition for flexible querying
		// The filter is appended to support complex predicates on event metadata
		query = fmt.Sprintf("%s AND (%s)", baseQuery, msg.Filter)
	} else {
		query = baseQuery
	}

	query += " ORDER BY created_at DESC LIMIT 50"

	rows, err := db.Query(query, msg.Channel)
	if err != nil {
		log.Printf("query error: %v", err)
		sendError(conn, "query failed")
		return
	}
	defer rows.Close()

	var events []map[string]interface{}
	for rows.Next() {
		var id int
		var eventType, payload string
		var createdAt string
		if err := rows.Scan(&id, &eventType, &payload, &createdAt); err != nil {
			continue
		}
		events = append(events, map[string]interface{}{
			"id":         id,
			"event_type": eventType,
			"payload":    payload,
			"created_at": createdAt,
		})
	}

	conn.WriteJSON(EventPayload{Type: "events", Data: events})
}

func isValidChannel(ch string) bool {
	if len(ch) == 0 || len(ch) > 64 {
		return false
	}
	for _, c := range ch {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') {
			return false
		}
	}
	return true
}

func sendError(conn *websocket.Conn, msg string) {
	conn.WriteJSON(EventPayload{Type: "error", Data: map[string]string{"message": msg}})
}

func sanitizeForLog(s string) string {
	return strings.ReplaceAll(s, "\n", "")
}

func main() {
	var err error
	db, err = sql.Open("postgres", "host=localhost port=5432 user=app dbname=events sslmode=disable")
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	http.HandleFunc("/ws", handleWebSocket)
	log.Println("WebSocket server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
